create or replace function public.mobile_create_client(p_company_id uuid,p_name text,p_phone text default null,p_whatsapp text default null,p_email text default null,p_address text default null) returns uuid language plpgsql security definer set search_path=public as $$ declare v_id uuid; begin if auth.uid() is null then raise exception 'No autenticado'; end if; if not exists(select 1 from company_members where company_id=p_company_id and user_id=auth.uid() and role in ('owner','admin','staff')) then raise exception 'Sin permiso'; end if; if nullif(trim(p_name),'') is null then raise exception 'Nombre requerido'; end if; insert into clients(company_id,name,phone,whatsapp,email,address,status,client_type) values(p_company_id,trim(p_name),nullif(trim(p_phone),''),nullif(trim(p_whatsapp),''),nullif(trim(p_email),''),nullif(trim(p_address),''),'active','person') returning id into v_id; return v_id; end $$;
revoke all on function public.mobile_create_client(uuid,text,text,text,text,text) from public,anon; grant execute on function public.mobile_create_client(uuid,text,text,text,text,text) to authenticated;

create or replace function public.mobile_convert_quote_to_work_order(p_quote_id uuid,p_due_at timestamptz default null,p_priority text default 'NORMAL') returns uuid language plpgsql security definer set search_path=public as $$ declare q quotes%rowtype; v_id uuid; begin if auth.uid() is null then raise exception 'No autenticado'; end if; select * into q from quotes where id=p_quote_id for update; if not found then raise exception 'Cotización no encontrada'; end if; if not exists(select 1 from company_members where company_id=q.company_id and user_id=auth.uid() and role in ('owner','admin','staff')) then raise exception 'Sin permiso'; end if; if q.status not in ('APPROVED','SENT') then raise exception 'La cotización debe estar enviada o aprobada'; end if; select id into v_id from work_orders where quote_id=q.id limit 1; if v_id is not null then return v_id; end if; if p_priority not in ('LOW','NORMAL','HIGH','URGENT') then raise exception 'Prioridad inválida'; end if; insert into work_orders(company_id,quote_id,client_id,status,title,due_at,total,priority,production_notes) values(q.company_id,q.id,q.client_id,'PENDING','Trabajo de cotización COT-'||q.number,p_due_at,q.total,p_priority,q.notes) returning id into v_id; insert into work_order_items(work_order_id,product_id,description,quantity,unit,unit_price,line_total,sort_order) select v_id,product_id,description,quantity,unit,unit_price,line_total,sort_order from quote_items where quote_id=q.id; update quotes set status='CONVERTED',updated_at=now() where id=q.id; return v_id; end $$;
revoke all on function public.mobile_convert_quote_to_work_order(uuid,timestamptz,text) from public,anon; grant execute on function public.mobile_convert_quote_to_work_order(uuid,timestamptz,text) to authenticated;

create or replace function public.mobile_register_customer_payment(p_receivable_id uuid,p_amount numeric,p_method text default 'CASH',p_reference text default null,p_notes text default null) returns uuid language plpgsql security definer set search_path=public as $$ declare r accounts_receivable%rowtype; v_id uuid; v_new numeric; begin if auth.uid() is null then raise exception 'No autenticado'; end if; select * into r from accounts_receivable where id=p_receivable_id for update; if not found then raise exception 'Cuenta por cobrar no encontrada'; end if; if not exists(select 1 from company_members where company_id=r.company_id and user_id=auth.uid() and role in ('owner','admin')) then raise exception 'Solo propietario o administrador puede registrar cobros'; end if; if p_amount<=0 then raise exception 'Monto inválido'; end if; if p_method not in ('CASH','TRANSFER','CARD','CHECK','OTHER') then raise exception 'Método inválido'; end if; if r.status in ('PAID','CANCELLED') then raise exception 'La cuenta no admite pagos'; end if; if r.amount_paid+p_amount>r.amount_total then raise exception 'El abono supera el saldo pendiente'; end if; insert into customer_payments(company_id,receivable_id,client_id,amount,payment_method,reference,notes) values(r.company_id,r.id,r.client_id,p_amount,p_method,nullif(trim(p_reference),''),nullif(trim(p_notes),'')) returning id into v_id; v_new:=r.amount_paid+p_amount; update accounts_receivable set amount_paid=v_new,status=case when v_new>=amount_total then 'PAID' else 'PARTIAL' end,updated_at=now() where id=r.id; return v_id; end $$;
revoke all on function public.mobile_register_customer_payment(uuid,numeric,text,text,text) from public,anon; grant execute on function public.mobile_register_customer_payment(uuid,numeric,text,text,text) to authenticated;
